 }

 /* subtle glow that follows the logo */
 #glow {
 position: absolute;
 left: inherit;
 top: inherit;
 width: calc(100% + 60px);
 height: calc(100% + 60px);
 transform: translate(-50%, -50%);
 pointer-events: none;
 background: radial-gradient(ellipse at center, rgba(255,237,71,0.18) 0%, transparent 70%);
 filter: blur(40px);
 animation: pulse 6s ease-in-out infinite;
 }

 @keyframes pulse {
 0%, 100% { opacity: 0.9; transform: translate(-50%, -50%) scale(1); }
 50% { opacity: 0.7; transform: translate(-50%, -50%) scale(1.02); }
 }

 /* optional: faint floor reflection */
 #reflection {
