 (function() {
 const logo = document.getElementById('logo');
 const glow = document.getElementById('glow');
 const reflection = document.getElementById('reflection');

 // Initial state: start from center with a gentle upward-right velocity
 let x = window.innerWidth / 2;
 let y = window.innerHeight / 2;
 let vx = (window.innerWidth * Math.random() + 0.5) * 1.8; // random direction
 let vy = -(Math.random() > 0.5 ? 3 : -3);

 const speedScale = 1.5; // how fast the logo moves each frame

 function update() {
 x += vx;
 y += vy;

 // Bounce off left/right walls
 if (x <= 0 || x >= window.innerWidth) {
 vx *= -1;
 }

 // Bounce off top/bottom walls
 if (y <= 0 || y >= window.innerHeight) {
 vy *= -1;
 }

